  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment=0.00) and model overestimates prices.",
    "Apply a lag correction: if true outcome is higher than forecast, reduce next forecast by 5-10% to avoid overshoot.",
    "When sentiment is positive (sentiment>0.00), increase forecast by 3-5% to capture upward momentum.",
    "For prices above 65.00, apply a mean reversion bias: reduce forecast by 2-5% if recent 7-day average is higher.",
    "After sharp spikes (forecast > 70.00), cap forecast at 75.00 for 3 days to prevent overcorrection.",
    "If true outcome is consistently 5-10% above forecast over 3 consecutive days, apply a 10% upward bias correction for next period."
  ]
}
